mapper.select:
select a.id,
       a.year,
       a.month,
       a.factory_code,
       a.product_code,
       a.product_desc,
       a.location_type,
       a.stock_qty,
       a.remark,
       a.is_delete,
       a.create_by,
       a.create_time,
       a.update_by,
       a.update_time,
       b.brand,
       b.specifications,
       b.pattern,
       b.pro_size
from T_MDM_PRODUCT_STOCK_MONTH a
left join T_MDM_MATERIAL_INFO b on b.IS_DELETE = 0
    and b.FACTORY_CODE = a.FACTORY_CODE
    and b.PRODUCT_CODE = a.PRODUCT_CODE
where a.IS_DELETE = 0

    and a.YEAR = #{year}


    and a.MONTH = #{month}


    and a.FACTORY_CODE = #{factoryCode}


    and a.PRODUCT_CODE = #{productCode}


    and a.LOCATION_TYPE = #{locationType}


    and b.PRODUCT_DESC = #{productDesc}


    and b.brand = #{brand}


    and b.specifications = #{specifications}


    and b.pattern = #{pattern}


    and b.proSize = #{proSize}
